const line = String(msg.payload ?? "").trim();

// Arduino가 출력하는 상태변경 설명문은 분석하지 않음
// 예: ==> SAFE -> WARNING
if (!line.startsWith("[state=")) {
    return null;
}

// 예시 입력:
// [state=SAFE] A=35cm (trig=no)  B=35cm (trig=no)
// [state=DANGER entry=A] A=10cm (trig=YES)  B=-1cm (trig=YES) [settling]

const pattern =
    /^\[state=(SAFE|WARNING|DANGER)(?:\s+entry=([AB]))?\]\s+A=(-?\d+)cm\s+\(trig=(YES|no)\)\s+B=(-?\d+)cm\s+\(trig=(YES|no)\)(?:\s+\[settling\])?$/i;

const match = line.match(pattern);

if (!match) {
    node.warn("Parse failed: " + line);
    return null;
}

msg.payload = {
    timestamp: Date.now(),

    state: match[1].toUpperCase(),
    entry: match[2] ? match[2].toUpperCase() : null,

    distanceA: Number(match[3]),
    triggeredA: match[4].toUpperCase() === "YES",

    distanceB: Number(match[5]),
    triggeredB: match[6].toUpperCase() === "YES",

    // 서보모터 움직임으로 센서가 흔들리는 500ms 구간
    settling: line.includes("[settling]")
};

msg.topic = "train_gate_sensor";

return msg;

const p = msg.payload;

if (!p || typeof p !== "object") {
    return null;
}

const now = Number(p.timestamp) || Date.now();

/*
 * 임시 판정 기준
 * 실제 기차 모형의 속도와 센서 간격에 맞춰 나중에 조정
 */
const MIN_DETECTION_MS = 300;  // 정상 감지는 최소 0.3초
const MIN_GAP_MS = 200;  // A와 B가 최소 0.2초 차이로 작동
const MAX_GAP_MS = 10000; // 다음 센서가 10초 안에 작동
const NOISE_WAIT_MS = 1000; // 순간 감지 후 1초 대기
const BLOCKED_MS = 5000; // 한 센서가 5초 이상 막힘
const FAULT_COUNT = 5;    // -1이 5회 연속 발생
const RECOVERY_COUNT = 10;   // 정상값 10회 연속이면 오류 복구
const CLEAR_COUNT = 3;    // 두 센서가 3회 연속 정상 해제

let s = context.get("validatorState") || {
    phase: "IDLE",

    first: null,
    firstAt: null,
    secondAt: null,
    firstClearedAt: null,

    aOnSince: null,
    bOnSince: null,
    lastDurationA: 0,
    lastDurationB: 0,

    errorA: 0,
    errorB: 0,
    totalErrorA: 0,
    totalErrorB: 0,

    faultLatched: false,
    validStreak: 0,
    clearStreak: 0
};

function saveAndReturn(output) {
    context.set("validatorState", s);
    return output;
}

function durationA() {
    if (s.aOnSince !== null) {
        return now - s.aOnSince;
    }
    return s.lastDurationA;
}

function durationB() {
    if (s.bOnSince !== null) {
        return now - s.bOnSince;
    }
    return s.lastDurationB;
}

function direction() {
    if (s.first === "A") return "A_TO_B";
    if (s.first === "B") return "B_TO_A";
    return null;
}

function makeResult(result, reason) {
    const colors = {
        NORMAL_PASS: "green",
        BLOCKED: "red",
        SENSOR_FAULT: "red",
        NOISE: "yellow",
        UNKNOWN: "grey"
    };

    node.status({
        fill: colors[result] || "grey",
        shape: "dot",
        text: result
    });

    return {
        topic: "ai_result",
        payload: {
            result: result,
            reason: reason,

            timestamp: new Date(now).toISOString(),
            arduinoState: p.state,
            entry: p.entry,

            direction: direction(),

            gap_ms:
                s.firstAt !== null && s.secondAt !== null
                    ? s.secondAt - s.firstAt
                    : null,

            duration_A_ms: durationA(),
            duration_B_ms: durationB(),

            error_count_A: s.totalErrorA,
            error_count_B: s.totalErrorB,

            distance_A_cm: p.distanceA,
            distance_B_cm: p.distanceB
        }
    };
}

function resetEvent() {
    s.phase = "IDLE";

    s.first = null;
    s.firstAt = null;
    s.secondAt = null;
    s.firstClearedAt = null;

    s.aOnSince = null;
    s.bOnSince = null;
    s.lastDurationA = 0;
    s.lastDurationB = 0;

    s.totalErrorA = 0;
    s.totalErrorB = 0;
    s.clearStreak = 0;

    node.status({
        fill: "green",
        shape: "ring",
        text: "MONITORING"
    });
}

/*
 * 서보모터가 움직이는 settling 구간은 센서 오류 계산에서 제외.
 * 현재 Arduino 코드에서 이 구간에 일시적인 -1이 발생할 수 있음.
 */
if (p.settling === true) {
    node.status({
        fill: "blue",
        shape: "ring",
        text: "SERVO SETTLING"
    });

    return saveAndReturn(null);
}

const invalidA =
    p.distanceA === null ||
    p.distanceA === undefined ||
    Number(p.distanceA) === -1;

const invalidB =
    p.distanceB === null ||
    p.distanceB === undefined ||
    Number(p.distanceB) === -1;

/*
 * 연속적인 -1 오류 횟수 계산
 */
if (invalidA) {
    s.errorA++;
    s.totalErrorA++;
} else {
    s.errorA = 0;
}

if (invalidB) {
    s.errorB++;
    s.totalErrorB++;
} else {
    s.errorB = 0;
}

/*
 * 센서 오류 판정
 */
if (s.errorA >= FAULT_COUNT || s.errorB >= FAULT_COUNT) {
    let output = null;

    if (!s.faultLatched) {
        s.faultLatched = true;
        s.phase = "WAIT_CLEAR";

        let faultySensor = "A and B";

        if (s.errorA >= FAULT_COUNT && s.errorB < FAULT_COUNT) {
            faultySensor = "A";
        } else if (
            s.errorB >= FAULT_COUNT &&
            s.errorA < FAULT_COUNT
        ) {
            faultySensor = "B";
        }

        output = makeResult(
            "SENSOR_FAULT",
            "Repeated -1 readings from sensor " + faultySensor
        );
    }

    return saveAndReturn(output);
}

/*
 * SENSOR_FAULT 이후 두 센서가 일정 시간 정상이어야 복구
 */
if (s.faultLatched) {
    if (!invalidA && !invalidB) {
        s.validStreak++;
    } else {
        s.validStreak = 0;
    }

    if (s.validStreak >= RECOVERY_COUNT) {
        s.faultLatched = false;
        s.validStreak = 0;
        resetEvent();
    }

    return saveAndReturn(null);
}

/*
 * 1~4회의 순간적인 -1은 바로 통과 판정에 사용하지 않고
 * 다음 정상 데이터를 기다림
 */
if (invalidA || invalidB) {
    return saveAndReturn(null);
}

/*
 * Arduino는 -1도 trig=YES로 보내므로
 * 반드시 유효한 거리값일 때만 실제 감지로 인정
 */
const activeA = Boolean(p.triggeredA) && !invalidA;
const activeB = Boolean(p.triggeredB) && !invalidB;

/*
 * 각 센서 감지 지속시간 계산
 */
if (activeA && s.aOnSince === null) {
    s.aOnSince = now;
}

if (!activeA && s.aOnSince !== null) {
    s.lastDurationA = now - s.aOnSince;
    s.aOnSince = null;
}

if (activeB && s.bOnSince === null) {
    s.bOnSince = now;
}

if (!activeB && s.bOnSince !== null) {
    s.lastDurationB = now - s.bOnSince;
    s.bOnSince = null;
}

/*
 * 이전 판정이 끝난 후 두 센서가 완전히 해제되는 것을 기다림
 */
if (s.phase === "WAIT_CLEAR") {
    if (!activeA && !activeB) {
        s.clearStreak++;
    } else {
        s.clearStreak = 0;
    }

    if (s.clearStreak >= CLEAR_COUNT) {
        resetEvent();
    }

    return saveAndReturn(null);
}

/*
 * 한쪽 센서가 너무 오래 막혀 있으면 BLOCKED
 */
const aBlocked =
    activeA &&
    s.aOnSince !== null &&
    now - s.aOnSince >= BLOCKED_MS;

const bBlocked =
    activeB &&
    s.bOnSince !== null &&
    now - s.bOnSince >= BLOCKED_MS;

if (aBlocked || bBlocked) {
    const blockedSensor =
        aBlocked && bBlocked ? "A and B" :
            aBlocked ? "A" : "B";

    const output = makeResult(
        "BLOCKED",
        "Sensor " + blockedSensor + " blocked for over 5 seconds"
    );

    s.phase = "WAIT_CLEAR";
    return saveAndReturn(output);
}

/*
 * 아무것도 감지되지 않은 대기 상태
 */
if (s.phase === "IDLE") {
    if (!activeA && !activeB) {
        node.status({
            fill: "green",
            shape: "ring",
            text: "MONITORING"
        });

        return saveAndReturn(null);
    }

    s.firstAt = now;
    s.firstClearedAt = null;
    s.secondAt = null;
    s.lastDurationA = 0;
    s.lastDurationB = 0;
    s.totalErrorA = 0;
    s.totalErrorB = 0;

    /*
     * 첫 샘플부터 A와 B가 동시에 감지되면 비정상 패턴
     */
    if (activeA && activeB) {
        const output = makeResult(
            "UNKNOWN",
            "Both sensors activated simultaneously"
        );

        s.phase = "WAIT_CLEAR";
        return saveAndReturn(output);
    }

    s.first = activeA ? "A" : "B";
    s.phase = "WAIT_SECOND";

    node.status({
        fill: "yellow",
        shape: "dot",
        text: "FIRST SENSOR: " + s.first
    });

    return saveAndReturn(null);
}

/*
 * 첫 번째 센서 작동 후 반대쪽 센서를 기다리는 단계
 */
if (s.phase === "WAIT_SECOND") {
    const firstActive =
        s.first === "A" ? activeA : activeB;

    const secondActive =
        s.first === "A" ? activeB : activeA;

    const firstDuration =
        s.first === "A" ? durationA() : durationB();

    if (!firstActive && s.firstClearedAt === null) {
        s.firstClearedAt = now;
    }

    /*
     * 반대쪽 센서가 작동함
     */
    if (secondActive) {
        s.secondAt = now;

        const gap = s.secondAt - s.firstAt;

        if (gap < MIN_GAP_MS) {
            const output = makeResult(
                "UNKNOWN",
                "A and B activated too close together"
            );

            s.phase = "WAIT_CLEAR";
            return saveAndReturn(output);
        }

        s.phase = "SECOND_ACTIVE";

        node.status({
            fill: "yellow",
            shape: "dot",
            text: "SECOND SENSOR DETECTED"
        });

        return saveAndReturn(null);
    }

    /*
     * 첫 센서가 아주 짧게 작동하고 반대 센서가 작동하지 않음
     */
    if (
        s.firstClearedAt !== null &&
        now - s.firstClearedAt >= NOISE_WAIT_MS &&
        firstDuration < MIN_DETECTION_MS
    ) {
        const output = makeResult(
            "NOISE",
            "Brief detection without activation of the opposite sensor"
        );

        s.phase = "WAIT_CLEAR";
        return saveAndReturn(output);
    }

    /*
     * 10초가 지나도 반대쪽 센서가 작동하지 않음
     */
    if (now - s.firstAt >= BLOCKED_MS) {
        const output = makeResult(
            "BLOCKED",
            "Opposite sensor did not activate within 5 seconds"
        );

        s.phase = "WAIT_CLEAR";
        return saveAndReturn(output);
    }

    return saveAndReturn(null);
}

/*
 * 반대쪽 센서가 작동한 후 해제되기를 기다림
 */
if (s.phase === "SECOND_ACTIVE") {
    const secondActive =
        s.first === "A" ? activeB : activeA;

    if (secondActive) {
        return saveAndReturn(null);
    }

    const gap = s.secondAt - s.firstAt;
    const firstDuration =
        s.first === "A" ? durationA() : durationB();

    const secondDuration =
        s.first === "A" ? durationB() : durationA();

    let output;

    if (
        gap >= MIN_GAP_MS &&
        gap <= MAX_GAP_MS &&
        firstDuration >= MIN_DETECTION_MS &&
        secondDuration >= MIN_DETECTION_MS
    ) {
        output = makeResult(
            "NORMAL_PASS",
            "Valid " + direction() + " passage sequence"
        );
    } else {
        output = makeResult(
            "UNKNOWN",
            "Passage sequence completed with abnormal timing"
        );
    }

    s.phase = "WAIT_CLEAR";
    return saveAndReturn(output);
}

return saveAndReturn(null);

const allowedLabels = [
    "NORMAL_PASS",
    "BLOCKED",
    "SENSOR_FAULT",
    "NOISE",
    "UNKNOWN"
];

const label = String(msg.payload || "").trim().toUpperCase();

if (!allowedLabels.includes(label)) {
    node.error("Invalid training label: " + label);
    return null;
}

// 선택한 정답을 Node-RED flow 메모리에 저장
flow.set("trainingLabel", label);

node.status({
    fill: "blue",
    shape: "dot",
    text: "LABEL: " + label
});

// 다른 노드로 메시지를 보낼 필요는 없음
return null;

const event = msg.payload;
const label = flow.get("trainingLabel");

if (!label) {
    node.warn("Select a training label before performing the test.");
    return null;
}

if (!event || typeof event !== "object") {
    return null;
}

function numberOr(value, fallback) {
    const number = Number(value);
    return Number.isFinite(number) ? number : fallback;
}

msg.payload = {
    timestamp: event.timestamp || new Date().toISOString(),

    // 사람이 선택한 실제 정답
    label: label,

    // 기존 규칙 기반 결과: 비교용이며 ML 입력 특징으로 사용하지 않음
    rule_result: event.result || "UNKNOWN",

    direction: event.direction || "NONE",
    arduino_state: event.arduinoState || "UNKNOWN",

    gap_ms: numberOr(event.gap_ms, -1),

    duration_A_ms: numberOr(event.duration_A_ms, 0),
    duration_B_ms: numberOr(event.duration_B_ms, 0),

    error_count_A: numberOr(event.error_count_A, 0),
    error_count_B: numberOr(event.error_count_B, 0),

    distance_A_cm: numberOr(event.distance_A_cm, -1),
    distance_B_cm: numberOr(event.distance_B_cm, -1)
};

flow.set("trainingLabel", null);

node.status({
    fill: "green",
    shape: "dot",
    text: "SAVED: " + label + " / SELECT NEXT LABEL"
});

return msg;

return msg;

const event = msg.payload;
msg.aiEvent = event;

if (!event || typeof event !== "object") {
    return null;
}

function numberOr(value, fallback) {
    const number = Number(value);
    return Number.isFinite(number) ? number : fallback;
}

const requestBody = {
    direction: event.direction || "NONE",
    arduino_state: event.arduinoState || "UNKNOWN",

    gap_ms: numberOr(event.gap_ms, -1),

    duration_A_ms: numberOr(event.duration_A_ms, 0),
    duration_B_ms: numberOr(event.duration_B_ms, 0),

    error_count_A: numberOr(event.error_count_A, 0),
    error_count_B: numberOr(event.error_count_B, 0),

    distance_A_cm: numberOr(event.distance_A_cm, -1),
    distance_B_cm: numberOr(event.distance_B_cm, -1)
};

msg.headers = {
    "content-type": "application/json"
};

msg.payload = JSON.stringify(requestBody);

return msg;

const result = msg.payload;

if (!result || typeof result !== "object" || !result.prediction) {
    return null;
}

flow.set("latestTrainAi", {
    prediction: result.prediction,
    confidence: Number(result.confidence || 0),
    action: result.action || "HOLD",
    open_candidate: result.open_candidate === true,
    savedAt: Date.now()
});

return msg;

const p = msg.payload;

if (!p || typeof p !== "object") {
    return null;
}

const ai = flow.get("latestTrainAi") || {};
const aiAge = Date.now() - Number(ai.savedAt || 0);
const aiFresh = aiAge < 6000;

const aiResult = aiFresh
    ? String(ai.prediction || "UNKNOWN").toUpperCase()
    : "MONITORING";

const arduinoState =
    String(p.state || "SAFE").toUpperCase();

/*
 * 기본 상태는 Arduino의 실제 상태를 따름
 */
let crossingStatus =
    arduinoState === "DANGER" ? "danger" :
        arduinoState === "WARNING" ? "warning" :
            "safe";

/*
 * 최근 AI 이상 판정은 더 안전한 상태로 덮어씀
 */
if (aiFresh) {
    if (
        aiResult === "BLOCKED" ||
        aiResult === "UNKNOWN" ||
        aiResult === "SENSOR_FAULT"
    ) {
        crossingStatus = "danger";
    } else if (
        aiResult === "NOISE" &&
        crossingStatus === "safe"
    ) {
        crossingStatus = "warning";
    }
}

let confidence = Number(ai.confidence || 0);

/*
 * Python 결과가 0~1이면 백분율로 변환
 */
if (confidence <= 1) {
    confidence *= 100;
}

confidence = Math.max(
    0,
    Math.min(100, confidence)
);

const distanceA = Number(p.distanceA);
const distanceB = Number(p.distanceB);

msg.payload = {
    distance_approach_cm:
        Number.isFinite(distanceA) ? distanceA : 999,

    distance_exit_cm:
        Number.isFinite(distanceB) ? distanceB : 999,

    entry_side:
        p.entry === "A" || p.entry === "B"
            ? p.entry
            : "none",

    speed_cms: 0,

    event_type: aiResult,

    status:
        crossingStatus === "safe"
            ? "normal"
            : crossingStatus,

    crossing_status: crossingStatus,

    gate_state:
        arduinoState === "SAFE"
            ? "open"
            : "closed",

    signal_state:
        arduinoState === "DANGER"
            ? "red"
            : arduinoState === "WARNING"
                ? "yellow"
                : "green",

    confidence:
        Math.round(confidence * 10) / 10,

    distance_km: 0,
    approach_speed_kmh: 0
};

msg.headers = {
    "Content-Type": "application/json"
};

return msg;
